INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:6F1E79E0', 'NSM:TO:TO_DESCEND_TO_REVEAL_COME_DOWN:XFA0A3478', 'lane_lexicon', 'blk_lane_794c465610075f51', 'gloss_support', 'Wherefore was not the Ḳur-án sent down, or revealed, to him] aggregated? (TA:) [or in one aggregate?] or at once?', 'direct_source', 'high', 'p.460 — on 25:32 نُزِّلَ … جُمْلَةً وَاحِدَةً, under جمل');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:C896CA04', 'NSM:TO:TO_DESCEND_TO_REVEAL_COME_DOWN:XC47D7BF9', 'lane_lexicon', 'blk_lane_f8e79568a923a65e', 'gloss_support', 'We have not sent down unto thee the Ḳur-án that thou shouldest suffer fatigue, but as an admonition', 'direct_source', 'high', 'p.76 — on 20:2 مَا أَنْزَلْنَا عَلَيْكَ ٱلقُرْآنَ, under الا');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:026BE49A', 'FRQ:M:hard_harsh:qaswa', 'lane_lexicon', 'blk_lane_c0a0dd77e837bf9d', 'gloss_support', 'mercy, compassion, or pity … in the soul, it is the contr. of جفوة and قسوة', 'direct_source', 'high', 'p.1131 — said of رِقَّة, tender-heartedness; under رقق');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:3870D0BE', 'FRQ:M:malik', 'lane_lexicon', 'blk_lane_642050fc17ea6851', 'gloss_support', 'مُلْكٌ signifies the exercise of authority to command and to forbid in respect of the generality of a people', 'direct_source', 'high', 'p.3023 — Lane citing al-Rāghib, under ملك');
