INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:EE767D1F', 'FRQ:M:dhikr_n', 'lane_lexicon', 'blk_lane_f218d50b35859975', 'gloss_support', 'A book containing an exposition of religion, and an institution of religious laws: (K:) any book of the prophets: (TA:) and especially the Kur-án', 'direct_source', 'high', 'p.969 — under ذكر');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:7C9C5D3B', 'NSM:PUNISHMENT:PUNISHMENT:X621E8326', 'lane_lexicon', 'blk_lane_12dc1ad47a01ae73', 'gloss_support', '[عاقبهُ as denoting consequence, and retaliation, or retribution, also signifies He punished him.]', 'direct_source', 'high', 'p.2099 — inf. n. عِقَاب; under عقب');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:4976EB50', 'NSM:SIN:SIN:X130AD92B', 'lane_lexicon', 'blk_lane_f58be1008e553e7f', 'gloss_support', 'or such as is intentional; (Ḳ;) like خِطْءٌ↓, (Ṣ, Ḳ;) which is an inf. n., thus used as a subst.; (Mṣb;) meaning a sin', 'direct_source', 'high', 'p.759 — said of خَطِيئَة, which Lane makes like خِطْء; under خطا');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:11B5D065', 'NSM:SIN:SIN:X193AC9FB', 'lane_lexicon', 'blk_lane_9ceb1b17e2ab43db', 'gloss_support', 'And أَلَمَّ بَالذَّنْبِ † He committed the sin, or offence.', 'direct_source', 'high', 'p.3013 — the verb behind لَمَم (53:32); Lane''s own entry لَمَمٌ (same page) gives only "slight insanity"; under لمم');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:2929E82B', 'NSM:SUFFICIENT:SUFFICIENT:X757A69A0', 'lane_lexicon', 'blk_lane_004d345d8b413ff6', 'gloss_support', 'signifies Beneficence; and bounty: (Ṣ, TA:) and [a benefit, a favour, a boon, or] a gift.', 'direct_source', 'high', 'p.1896 — under طول');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:CB8D7CB8', 'NSM:SUFFICIENT:SUFFICIENT:X757A69A0', 'lane_lexicon', 'blk_lane_2004f79e897850bc', 'gloss_support', 'Excellence, excess, or superabundance: and power, or ability: and wealth, or competence: and ampleness of circumstances', 'direct_source', 'high', 'p.1896 — under طول');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:749319B2', 'NSM:SUFFICIENT:SUFFICIENT:X51CED7CE', 'lane_lexicon', 'blk_lane_f1a774d470382839', 'gloss_support', 'An exceeding, a redundant, or a superfluous, quantum [of anything, good or evil]; an excess, a redundance, or a superfluity; syn. زِيَادَةٌ', 'direct_source', 'high', 'p.2412 — under فضل');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:AF0E70FB', 'NSM:SUFFICIENT:SUFFICIENT:X51CED7CE', 'lane_lexicon', 'blk_lane_c1bbde7e937473bb', 'gloss_support', 'he bestowed, or conferred, a benefit, or benefits, upon him, syn. أَحْسَنَ, (Ṣ, TA,) or تَطَوَّلَ, (Ḳ, TA,) and gave him of his bounty', 'direct_source', 'high', 'p.2412 — said of أَفْضَلَ عَلَيْهِ — Lane ties it to تَطَوَّلَ (طَوْل); under فضل');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:AF1DD587', 'NSM:TO:TO_ACCEPT:X9ED9493A', 'lane_lexicon', 'blk_lane_d499265863bca32a', 'gloss_support', 'I have repented toward Thee, and accept Thou my repentance; and I have fasted, O my Lord, and accept Thou my fast', 'direct_source', 'high', 'p.321 — a verse with تَقَبَّلْ twice; under توب');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:B0BB22AA', 'NSM:TO:TO_ACCEPT:X37DF002C', 'lane_lexicon', 'blk_lane_86178d9d6b4f5292', 'gloss_support', 'He took, received, or admitted, willingly, or with approbation; he accepted.', 'direct_source', 'high', 'p.28 — Lane gives the same words for قَبِلَ (blk_lane_5f490dd1ca203137, p.2983); under اخذ');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:6FE61D23', 'NSM:TO:TO_ACCEPT:X19F55FCD', 'lane_lexicon', 'blk_lane_825fef0fad3644ba', 'gloss_support', 'said of God, (Ṣ, A, Mṣb, TA,) [He answered his prayer;;] He accepted his prayer; (Mṣb;) He recompensed his prayer by gift and acceptance.', 'direct_source', 'high', 'p.479 — اسْتَجَابَ دُعَاءَهُ; under جوب');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:2526AECC', 'NSM:TO:TO_RETURN:XBB6D78AE', 'lane_lexicon', 'blk_lane_28742a1672cb75fb', 'gloss_support', '[but this is a loose explanation; the meaning being, The thing, or affair, or case, came eventually (see صِيرٌ) to such a state, or condition:]', 'direct_source', 'high', 'p.1754 — on صَارَ الأَمْرُ إِلَى كَذَا, which Mṣb glosses رَجَعَ إِلَيْهِ; under صير');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:60063EBB', 'NSM:PUNISHMENT:PUNISHMENT:X621E8326', 'lane_lexicon', 'blk_lane_48c0c126eaf166b2', 'gloss_support', 'عُقُوبَةٌ Punishment; (Ṣ,* MA, Mṣb,* KL;) i. q. نَكَالٌ. (MA.)', 'direct_source', 'high', 'p.2103 — عُقُوبَة, the sister noun of عِقَاب; Lane makes it i. q. نَكَال (a member); under عقب');

-- ===== Step 2 — missing member: FRQ:SET:kitab_names · ٱلصُّحُف (صُحُف, canonical e85d68d4716ff4f467af6aac16)
-- Lane p.1655 makes صَحِيفَة «syn. كِتَابٌ»; al-Rāghib p.476 says how they differ: a صَحِيفَة is a flat, spread sheet one writes on,
-- and on 98:2–3 «صحفا فيها كتب» — the books are written inside the sheets. Maqāyīs p.44: the root means spreading out.
-- (set, lemma) pair checked: not in the live DB, not elsewhere in this batch.
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member (id, set_id, lemma_id, nuance_note, arabic_display, arabic_bare, basic_gloss, contrast_note, source_status, claim_basis, confidence, sort_order) VALUES ('FRQ:M:suhuf_n', 'FRQ:SET:kitab_names', 'e85d68d4716ff4f467af6aac16', 'named for the flat sheets the books are written on', 'ٱلصُّحُف', 'صحف', 'written sheets — the pages of a scripture', 'named for the flat sheets the books are written on', 'lexicon_checked', 'direct_source', 'high', 6);
