INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_evidence (id, set_id, member_id, lemma_id, qr_ref, surah, ayah, word_index, arabic_quote, evidence_type, confidence, validation_status, note_md) VALUES ('NSE:111F3203', 'FRQ:SET:kitab_names', 'FRQ:M:suhuf_n', 'e85d68d4716ff4f467af6aac16', 'QR:98:2:5', 98, 2, 5, 'يَتۡلُواْ صُحُفٗا مُّطَهَّرَةٗ', 'quran_usage', 'high', 'checked', 'needle: يتلوا صحفا مطهرة');
UPDATE ar_ling_root_lemma_furuq_set_src SET note_md = 'كِتَاب is named for being written; قُرْءَان for being recited; فُرْقَان for telling truth from falsehood; ذِكْر for bringing truth to mind; زُبُر for firm writing; صُحُف for the flat sheets the books are written on. — al-Rāghib pp. 699, 668, 632, 328, 377, 476; Lane pp. 2499, 2385, 1209, 1655' WHERE id = 'NSS:FRQ:SET:kitab_names:contrast' AND instr(note_md, 'صُحُف') = 0;
UPDATE ar_ling_root_lemma_furuq_set SET canonical_ar = canonical_ar || ' · ٱلصُّحُف', updated_at = datetime('now') WHERE id = 'FRQ:SET:kitab_names' AND canonical_ar IS NOT NULL AND instr(canonical_ar, 'ٱلصُّحُف') = 0;

